/* PC HTML export bundle: pure, reusable by mobile app and legacy-file upgrader. */
export async function editableReportHTML(report){
 const source=await fetch('pc-editor-runtime.js');if(!source.ok)throw new Error('PC編集機能を読み込めません');
 const runtime=await source.text();
 if(!runtime.includes('function renameLinkedPlace')||!runtime.includes('function addPhotos'))throw new Error('PC編集機能が不完全です');
 const toolbar=`<section id="pcEditToolbar"><div class="pc-edit-heading"><strong>Field REPORT｜PC編集モード</strong><span>報告書を後から仕上げる。写真の追加と、同じ場所の写真をまとめて修正できます。</span></div><div class="pc-edit-actions"><button type="button" id="pcAddPhotoButton">＋ 写真を追加</button><button type="button" id="pcRenamePlaceButton">場所名をまとめて変更</button><button type="button" id="saveEditedHTMLButton">編集済みHTMLを保存</button><button type="button" id="pcPrintButton">PDF / 印刷</button></div><p id="pcEditStatus" role="status">編集内容はHTMLファイルとして保存します。</p><div id="pcAddPanel" class="pc-edit-panel" hidden><label>施工工程<select id="pcWorkCategory"></select></label><label>場所名<input id="pcPlaceName" placeholder="例：1F・厨房"></label><label>追加する写真（複数可）<input id="pcAddFiles" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple></label><button type="button" id="pcAddConfirm">この場所に写真を追加</button><button type="button" id="pcAddClose">閉じる</button></div><div id="pcRenamePanel" class="pc-edit-panel" hidden><label>変更前の場所<select id="pcOldPlace"></select></label><label>変更後の場所名<input id="pcNewPlace" placeholder="例：2F・調理場"></label><button type="button" id="pcRenameConfirm">同じ場所の写真をまとめて変更</button><button type="button" id="pcRenameClose">閉じる</button></div></section>`;
 const style=`<style id="pcEditStyle">#pcEditToolbar{position:sticky;top:0;z-index:9999;display:grid;gap:10px;padding:13px 16px;background:#171815;color:#fff;box-shadow:0 2px 12px #0003;font-family:-apple-system,BlinkMacSystemFont,"Hiragino Sans","Yu Gothic",sans-serif}#pcEditToolbar .pc-edit-heading{display:flex;flex-wrap:wrap;gap:10px;align-items:center}#pcEditToolbar .pc-edit-heading span{font-size:13px;opacity:.86}#pcEditToolbar .pc-edit-actions{display:flex;gap:7px;flex-wrap:wrap}#pcEditToolbar button,.pc-group-actions button{border:1px solid #b9c5b6;border-radius:9px;padding:9px 11px;background:#fff;color:#1b2519;font:inherit;font-size:13px;font-weight:750;cursor:pointer}#pcEditStatus{margin:0;font-size:12px;color:#fcdf8c}.pc-edit-panel{background:#f0f1eb;color:#171815;padding:12px;border-radius:12px;display:flex;flex-wrap:wrap;gap:10px;align-items:end}.pc-edit-panel[hidden]{display:none!important}.pc-edit-panel label{display:grid;gap:4px;font-size:12px;font-weight:700}.pc-edit-panel input,.pc-edit-panel select{box-sizing:border-box;width:100%;max-width:300px;min-width:140px;padding:9px;font-size:14px}.pc-group-actions{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.pc-group-actions button{border-color:#a3b0a3;background:#eef6ea}.pc-editable{outline:1px dashed transparent}.pc-editable:hover,.pc-editable:focus{outline:2px solid #76a8ff;outline-offset:3px;background:#eef5ff}.pc-image-editable{cursor:pointer;outline:2px dashed transparent;outline-offset:2px}.pc-image-editable:hover{outline-color:#76a8ff}@media print{#pcEditToolbar,.pc-dynamic-control{display:none!important}.pc-editable,.pc-image-editable{outline:none!important;background:transparent!important}}</style>`;
 // The exported file is self-contained. No JavaScript is fetched when PC users reopen it.
 const script='<script id="pcEditScript">'+runtime.replace(/<\/script/gi,'<\\/script')+'</script>';
 return String(report.html||'').replace('</head>',style+'</head>').replace('<body>','<body>'+toolbar).replace('</body>',script+'</body>');
}
